function emptyData(){return{likes:{},gifts:{},comments:{},interact:{},giftBy:{},giftTot:{},recentGifts:[],recentFollows:[],
 tot:{likes:0,gifts:0,giftCount:0,comments:0,follows:0,subs:0},feed:[],startedAt:Date.now(),running:true}}

function applyEvent(D,H,ev){
 if(!D.interact){D.interact={};D.recentGifts=[];D.recentFollows=[];D.tot.follows=D.tot.follows||0;D.tot.subs=D.tot.subs||0}
 const u=ev.user||{}; const k=u.id||u.name;
 const base=k?{k,name:u.name||k,av:u.avatar||""}:null;
 const inter=n=>{ if(!base) return; const r=D.interact[k]||(D.interact[k]={...base,v:0}); r.v+=n; if(base.av) r.av=base.av };
 if(ev.type==="like"){ if(!base) return; const n=Math.max(0,+ev.count||0); const r=D.likes[k]||(D.likes[k]={...base,v:0}); r.v+=n; r.av=base.av||r.av; D.tot.likes+=n; inter(1) }
 else if(ev.type==="gift"){ if(!base) return; const val=Math.max(0,+ev.value||0), cnt=Math.max(1,+ev.count||1); const r=D.gifts[k]||(D.gifts[k]={...base,v:0,c:0}); r.v+=val; r.c+=cnt; D.tot.gifts+=val; D.tot.giftCount+=cnt;
   if(ev.giftId!=null||ev.gift){ const gk=String(ev.giftId??ev.gift); D.giftBy=D.giftBy||{}; D.giftTot=D.giftTot||{}; const gb=D.giftBy[gk]||(D.giftBy[gk]={}); const gr=gb[k]||(gb[k]={...base,v:0}); gr.v+=cnt; D.giftTot[gk]=(D.giftTot[gk]||0)+cnt; (D.giftNames=D.giftNames||{})[gk]=ev.gift||gk }
   D.recentGifts.unshift({k:k+"#"+(ev.id||ev.t||Date.now()),name:base.name,av:base.av,v:val,t:ev.t||Date.now()}); D.recentGifts.length=Math.min(D.recentGifts.length,30); inter(cnt);
   if(H){H.push({k,name:base.name,av:base.av,v:val,c:cnt,t:ev.t||Date.now()}); if(H.length>20000) H.splice(0,H.length-20000)} }
 else if(ev.type==="comment"){ if(!base) return; const r=D.comments[k]||(D.comments[k]={...base,v:0}); r.v+=1; D.tot.comments++; D.feed.unshift({name:base.name,text:String(ev.text||"").slice(0,200),t:Date.now()}); D.feed.length=Math.min(D.feed.length,60); inter(1) }
 else if(ev.type==="follow"){ if(!base) return; D.tot.follows++; D.recentFollows=D.recentFollows.filter(x=>x.k!==k); D.recentFollows.unshift({...base,v:0,t:ev.t||Date.now()}); D.recentFollows.length=Math.min(D.recentFollows.length,30) }
 else if(ev.type==="subscribe"){ D.tot.subs++ }
 else if(ev.type==="share"){ D.tot.shares=(D.tot.shares||0)+1 }
 else if(ev.type==="reset"){ const s=ev.scope||"all";
   if(s==="likes"||s==="all"){D.likes={};D.tot.likes=0}
   if(s==="gifts"||s==="all"){D.gifts={};D.tot.gifts=0;D.tot.giftCount=0;D.recentGifts=[];D.giftBy={};D.giftTot={}}
   if(s==="comments"||s==="all"){D.comments={};D.tot.comments=0;D.feed=[]}
   if(s==="interact"||s==="all"){D.interact={}}
   if(s==="follows"||s==="all"){D.recentFollows=[];D.tot.follows=0} }
 else if(ev.type==="shuffle"){ const b=D[ev.scope]; if(!b||Array.isArray(b)) return; const arr=Object.values(b).sort((a,b)=>b.v-a.v); if(arr.length<2) return; const pick=arr[1+Math.floor(Math.random()*(arr.length-1))]; const add=arr[0].v-pick.v+1+Math.floor(Math.random()*20); pick.v+=add; if(ev.scope==="likes")D.tot.likes+=add; if(ev.scope==="gifts")D.tot.gifts+=add; }
}
/** أي القوائم تتأثر بحدث reset/shuffle */
const SCOPE_OF={likes:["likes","interact"],gifts:["gifts","recentGifts","interact"],comments:["comments","interact"],interact:["interact"],follows:["recentFollows"]};

function entries(w,D,H){
 let list;
 const vals=o=>Object.values(o||{}).map(r=>({k:r.k,name:r.name,av:r.av,v:r.v}));
 if(w.type==="likes") list=vals(D.likes);
 else if(w.type==="comments") list=vals(D.comments);
 else if(w.type==="interact") list=vals(D.interact);
 else if(w.type==="recentGifts") return (D.recentGifts||[]).slice(0,w.topN).map(r=>({...r}));
 else if(w.type==="recentFollows") return (D.recentFollows||[]).slice(0,w.topN).map(r=>({...r}));
 else if(w.type==="gifts"){
  const by=w.sortBy||"value";
  if(by==="value"||by==="session") list=Object.values(D.gifts).map(r=>({k:r.k,name:r.name,av:r.av,v:r.v,c:r.c}));
  else if(by==="count") list=Object.values(D.gifts).map(r=>({k:r.k,name:r.name,av:r.av,v:r.c,c:r.v}));
  else { const now=new Date(); let since;
   if(by==="day"){since=new Date(now.getFullYear(),now.getMonth(),now.getDate()).getTime()}
   else if(by==="week"){since=Date.now()-7*864e5} else since=Date.now()-30*864e5;
   const m={}; for(const e of (H||[])) if(e.t>=since){const r=m[e.k]||(m[e.k]={k:e.k,name:e.name,av:e.av,v:0,c:0}); r.v+=e.v; r.c+=e.c}
   list=Object.values(m);
  }
 } else list=[];
 return list.sort((a,b)=>b.v-a.v||a.name.localeCompare(b.name)).slice(0,w.topN);
}

/* ---- engine/clock.js ---- */
// ====== محرك المؤقتات والسبثون ======
// دوال نقية: كل عملية تأخذ "now" من الخادم، والحالة تُخزَّن كـ endsAt (وقت انتهاء مطلق) أثناء التشغيل
// أو remainingMs أثناء الإيقاف. لذلك لا يضيع الوقت عند تحديث الصفحة أو إغلاق المتصفح أو إعادة تشغيل الخادم.
const MIN=60000, HOUR=3600000;

function defaultGiftRules(){ // قيم افتراضية تجريبية — قابلة للتعديل بالكامل
 return [{giftId:5655,name:"وردة",sec:5},{giftId:5487,name:"قلب",sec:10},{giftId:5879,name:"دونات",sec:30},{giftId:null,name:"هدية متوسطة",sec:120,minDiamonds:500},{giftId:6369,name:"أسد",sec:1800},{giftId:7312,name:"يونيفرس",sec:3600}];
}
function newSubathon(o={}){
 const initial=2*HOUR;
 return Object.assign({id:"sa_"+Math.random().toString(36).slice(2,9),name:"سبثون",desc:"",status:"idle",
  initialMs:initial,remainingMs:initial,endsAt:null,startedAt:null,scheduledAt:null,endedAt:null,
  minMs:0,maxMs:72*HOUR,maxTotalMs:0,totalAddedMs:0,
  pauseOnDisconnect:true,autoPaused:false,countWhilePaused:true,
  rules:{
   gifts:{enabled:true,table:defaultGiftRules(),perDiamondSec:0},
   likes:{enabled:true,every:1000,sec:30},
   follow:{enabled:true,sec:10},
   subscribe:{enabled:true,sec:300},
   goal:{enabled:false,metric:"likes",target:10000,sec:600,reached:false},
   manual:{enabled:true},
   auto:true,
   list:defaultRuleList(),
  },
  rstate:{acc:{},last:{},user:{},win:{}},
  likeAcc:0, seq:0},o);
}
function remaining(s,now){ return s.status==="running"?Math.max(0,s.endsAt-now):Math.max(0,s.remainingMs) }

function setRemaining(s,ms,now){ if(s.status==="running") s.endsAt=now+ms; else s.remainingMs=ms }
function log(s,now,deltaMs,requestedMs,reason,source,eventId,x){ s.seq=(s.seq||0)+1; return Object.assign({subathonId:s.id,seq:s.seq,deltaMs,requestedMs,reason,source,eventId:eventId||null,at:now,remainingMs:remaining(s,now)},x||{}) }

/** عملية تحكم: start | pause | resume | add | reset | end | config — ترجع سجلات العمليات */
function subathonOp(s,op,now){
 const out=[];
 switch(op.op){
  case "start":
   if(s.status==="running") break;
   if(s.status==="ended"){ s.remainingMs=s.initialMs; s.totalAddedMs=0; s.likeAcc=0; s.rules.goal.reached=false }
   if(s.status==="paused"){ s.endsAt=now+s.remainingMs; s.status="running"; s.autoPaused=false; out.push(log(s,now,0,0,"استكمال","control")); break }
   s.status="running"; s.startedAt=now; s.endsAt=now+s.remainingMs; s.endedAt=null; s.autoPaused=false;
   out.push(log(s,now,0,0,"بدء السبثون","control")); break;
  case "pause":
   if(s.status!=="running") break;
   s.remainingMs=remaining(s,now); s.endsAt=null; s.status="paused"; s.autoPaused=!!op.auto;
   out.push(log(s,now,0,0,op.auto?"إيقاف تلقائي (انقطاع البث)":"إيقاف مؤقت","control")); break;
  case "resume":
   if(s.status!=="paused") break;
   s.endsAt=now+s.remainingMs; s.status="running"; s.autoPaused=false;
   out.push(log(s,now,0,0,op.auto?"استكمال تلقائي (عودة البث)":"استكمال","control")); break;
  case "add": {
   if(s.status==="ended") break;
   const manual=op.source==="manual";
   if(manual&&!s.rules.manual.enabled) break;
   let req=Math.round(+op.ms||0); if(!req) break;
   const cur=remaining(s,now);
   let delta=req;
   if(delta>0&&s.maxTotalMs>0) delta=Math.min(delta,Math.max(0,s.maxTotalMs-s.totalAddedMs));
   let next=cur+delta;
   if(s.maxMs>0) next=Math.min(next,s.maxMs);
   if(req<0) next=Math.max(next,Math.min(cur,s.minMs)); // الخصم لا ينزل تحت الحد الأدنى
   next=Math.max(0,next);
   const applied=next-cur; if(!applied&&req>0){ out.push(log(s,now,0,req,(op.reason||"إضافة")+" (وصل الحد الأقصى)",op.source||"manual",op.eventId,op.x)); break }
   setRemaining(s,next,now); if(applied>0) s.totalAddedMs+=applied;
   out.push(log(s,now,applied,req,op.reason||(req>0?"إضافة يدوية":"خصم يدوي"),op.source||"manual",op.eventId,op.x));
   if(s.status==="running"&&next===0){ s.status="ended"; s.endedAt=now; s.remainingMs=0; s.endsAt=null; out.push(log(s,now,0,0,"انتهى السبثون","system")) }
   break }
  case "reset":
   s.status="idle"; s.remainingMs=s.initialMs; s.endsAt=null; s.startedAt=null; s.endedAt=null; s.totalAddedMs=0; s.likeAcc=0; s.rules.goal.reached=false; s.autoPaused=false;
   out.push(log(s,now,0,0,"إعادة ضبط","control")); break;
  case "end":
   if(s.status==="ended") break;
   s.status="ended"; s.endedAt=now; s.remainingMs=0; s.endsAt=null;
   out.push(log(s,now,0,0,"إنهاء السبثون","control")); break;
  case "config": { // تعديل الإعدادات (لا يغيّر الوقت الجاري إلا initialMs عند الخمول)
   const c=op.config||{};
   for(const k of ["name","desc","minMs","maxMs","maxTotalMs","pauseOnDisconnect","countWhilePaused","scheduledAt"]) if(c[k]!==undefined) s[k]=c[k];
   if(c.initialMs!==undefined){ s.initialMs=Math.max(MIN,+c.initialMs); if(s.status==="idle") s.remainingMs=s.initialMs }
   if(c.rules) for(const r in c.rules){ if(r==="list"&&Array.isArray(c.rules.list)) s.rules.list=c.rules.list.map(x=>Object.assign(newRule(x.kind||"gift"),x)); else if(typeof c.rules[r]!=="object"||c.rules[r]===null) s.rules[r]=c.rules[r]; else s.rules[r]=Object.assign(s.rules[r]||{},c.rules[r]) }
   if(c.rules&&Array.isArray(s.rules.list)) syncLegacy(s,c.rules);
   break }
 }
 return out;
}

/** قيمة الوقت لهدية حسب جدول المستخدم (بالمعرّف أولاً ثم الاسم ثم حد الألماس ثم قيمة لكل ألماسة) */
function giftSeconds(rules,ev){
 const g=rules.gifts; if(!g||!g.enabled) return 0;
 const id=ev.giftId!=null?String(ev.giftId):null, name=String(ev.gift||"").trim().toLowerCase();
 const per=(ev.diamonds!=null?+ev.diamonds:(+ev.value||0)/Math.max(1,+ev.count||1));
 let row=(id&&g.table.find(r=>r.giftId!=null&&String(r.giftId)===id))||(name&&g.table.find(r=>r.giftId==null&&!r.minDiamonds&&String(r.name).trim().toLowerCase()===name));
 if(!row){ const tiers=g.table.filter(r=>r.giftId==null&&r.minDiamonds>0&&per>=r.minDiamonds).sort((a,b)=>b.minDiamonds-a.minDiamonds); row=tiers[0] }
 const cnt=Math.max(1,+ev.count||1);
 if(row) return row.sec*cnt;
 return (g.perDiamondSec||0)*per*cnt;
}

// ================= محرك قواعد التفاعل (لكل قاعدة معرّف مستقل) =================
const RULE_KINDS={gift:{label:"هدية TikTok",icon:"🎁"},follow:{label:"متابعة جديدة",icon:"💚"},subscribe:{label:"اشتراك مدفوع",icon:"⭐"},likes:{label:"تكبيس (إعجابات)",icon:"❤️"},share:{label:"مشاركة البث",icon:"🔁"},comment:{label:"أمر في التعليقات",icon:"💬"},donation:{label:"دونيشن مالي",icon:"💰"}};
const rid=()=>"r_"+Math.random().toString(36).slice(2,9);
function newRule(kind="gift",o={}){
 return Object.assign({id:rid(),kind,enabled:true,dir:1,ms:60000,every:1,giftId:null,giftName:"",emoji:"",img:"",minDiamonds:0,perDiamondMs:0,
  keyword:"",cooldownMs:0,userCooldownMs:0,perMin:0,maxMs:0,sound:true,show:true,label:"",
  currency:"SAR",unit:1,addMs:120000,subMs:60000,addWords:"زيد,زود,+",subWords:"نقص,انقص,-",defaultAction:"add",minAmount:0},o);
}
/** القيم الافتراضية من المواصفات — قابلة للتعديل بالكامل */
function defaultRuleList(){ return [
 newRule("follow",{ms:60000,emoji:"💚"}),
 newRule("subscribe",{ms:10*60000,emoji:"⭐"}),
 newRule("likes",{every:1000,ms:60000,emoji:"❤️"}),
 newRule("share",{every:10,ms:2*60000,emoji:"🔁",enabled:false}),
 newRule("gift",{giftId:5655,giftName:"وردة",emoji:"🌹",ms:5000}),
 newRule("gift",{giftId:6369,giftName:"أسد",emoji:"🦁",ms:30*60000}),
 newRule("gift",{giftId:7312,giftName:"يونيفرس",emoji:"🌌",ms:60*60000,dir:-1}),
 newRule("donation",{currency:"SAR",unit:1,addMs:2*60000,subMs:60000,emoji:"💰"}),
 newRule("comment",{keyword:"زيد",ms:10000,userCooldownMs:60000,perMin:10,emoji:"💬",enabled:false}),
 newRule("comment",{keyword:"نقص",ms:10000,dir:-1,userCooldownMs:60000,perMin:10,emoji:"💬",enabled:false}),
]}
/** ترقية إعدادات قديمة (جدول الهدايا + الإعجابات + المتابعة + الاشتراك) إلى قائمة قواعد دون تغيير سلوكها */
function migrateRules(s){
 const R=s.rules=s.rules||{}; s.rstate=s.rstate||{acc:{},last:{},user:{},win:{}};
 if(R.auto===undefined) R.auto=true;
 if(Array.isArray(R.list)) return s;
 const L=[];
 if(R.follow) L.push(newRule("follow",{ms:(R.follow.sec||0)*1000,enabled:!!R.follow.enabled,emoji:"💚"}));
 if(R.subscribe) L.push(newRule("subscribe",{ms:(R.subscribe.sec||0)*1000,enabled:!!R.subscribe.enabled,emoji:"⭐"}));
 if(R.likes) L.push(newRule("likes",{every:R.likes.every||1000,ms:(R.likes.sec||0)*1000,enabled:!!R.likes.enabled,emoji:"❤️"}));
 L.push(newRule("share",{every:10,ms:120000,enabled:false,emoji:"🔁"}));
 const g=R.gifts; if(g){ for(const r of g.table||[]) L.push(newRule("gift",{giftId:r.giftId??null,giftName:r.name||"",minDiamonds:r.minDiamonds||0,ms:(r.sec||0)*1000,enabled:!!g.enabled,emoji:"🎁"}));
  if(g.perDiamondSec>0) L.push(newRule("gift",{giftId:"*",giftName:"أي هدية أخرى",perDiamondMs:g.perDiamondSec*1000,ms:0,enabled:!!g.enabled})) }
 L.push(newRule("donation",{enabled:false,emoji:"💰"}));
 R.list=L; return s;
}
/** توافق: تعديل الإعدادات بالصيغة القديمة (follow/subscribe/likes/gifts) ينعكس على قائمة القواعد */
function syncLegacy(s,c){ const L=s.rules.list;
 for(const k of ["follow","subscribe"]) if(c[k]) for(const r of L.filter(x=>x.kind===k)){ if(c[k].enabled!==undefined) r.enabled=!!c[k].enabled; if(c[k].sec!==undefined) r.ms=c[k].sec*1000 }
 if(c.likes) for(const r of L.filter(x=>x.kind==="likes")){ if(c.likes.enabled!==undefined) r.enabled=!!c.likes.enabled; if(c.likes.every!==undefined) r.every=c.likes.every; if(c.likes.sec!==undefined) r.ms=c.likes.sec*1000 }
 if(c.gifts){ if(c.gifts.table){ const keep=L.filter(x=>x.kind!=="gift"); const g=s.rules.gifts; const add=c.gifts.table.map(r=>newRule("gift",{giftId:r.giftId??null,giftName:r.name||"",minDiamonds:r.minDiamonds||0,ms:(r.sec||0)*1000,enabled:g.enabled!==false,emoji:"🎁"})); s.rules.list=L.splice(0,L.length,...keep,...add)&&[...keep,...add] }
  if(c.gifts.enabled!==undefined) for(const r of s.rules.list.filter(x=>x.kind==="gift")) r.enabled=!!c.gifts.enabled }
}
/** نص القاعدة كما يظهر للمشاهد — يُقرأ دائماً من الإعدادات الحالية */
function fmtDur(ms,short){ const a=Math.abs(ms), s=Math.round(a/1000);
 if(short){ if(s<60) return s+"s"; if(s<3600) return (+(s/60).toFixed(1))+"m"; return (+(s/3600).toFixed(1))+"h" }
 const p=durParts(ms); return `${p.n} ${p.unit}` }
/** الرقم والوحدة منفصلان حتى تُعرض العلامة والرقم معاً بالاتجاه الصحيح في العربية */
function durParts(ms){ const s=Math.round(Math.abs(ms)/1000), u=(n,one,few)=>({n,unit:n>2&&n<=10&&Number.isInteger(n)?few:one});
 if(s<60) return u(s,"ثانية","ثوانٍ"); if(s<3600) return u(+(s/60).toFixed(1),"دقيقة","دقائق"); return u(+(s/3600).toFixed(1),"ساعة","ساعات") }
const signed=ms=>{ const p=durParts(ms); return `\u2066${ms<0?"-":"+"}${p.n}\u2069 ${p.unit}` };
const CUR_AR={SAR:"ريال",AED:"درهم",KWD:"دينار",USD:"دولار",EUR:"يورو",QAR:"ريال قطري",BHD:"دينار بحريني",OMR:"ريال عماني"};
function ruleView(r){
 const k=RULE_KINDS[r.kind]||RULE_KINDS.gift, sg=r.dir<0?"-":"+";
 const icon=r.emoji||k.icon, img=r.img||"";
 let what="", ms=r.ms*(r.dir<0?-1:1), rows=null;
 switch(r.kind){
  case "follow": what="فولو"; break;
  case "subscribe": what="اشتراك"; break;
  case "likes": what=`${(+r.every||1).toLocaleString("en-US")} لايك`; break;
  case "share": what=(+r.every>1?`${r.every} مشاركات`:"مشاركة"); break;
  case "comment": what=`اكتب «${r.keyword}»`; break;
  case "gift": what=(r.giftId==="*"?"أي هدية":r.giftName||("هدية "+(r.giftId??"")))+(+r.every>1?` ×${r.every}`:"")+(r.minDiamonds>0&&r.giftId==null?` (${r.minDiamonds}💎+)`:""); if(r.perDiamondMs&&!r.ms){ ms=r.perDiamondMs; what+=" لكل 💎" } break;
  case "donation": { const u=`${r.unit||1} ${CUR_AR[r.currency]||r.currency}`; rows=[];
   if(r.addMs>0) rows.push({icon,what:`دونيشن ${u} + زيد`,ms:r.addMs,text:signed(r.addMs),short:`+${fmtDur(r.addMs,1)}`});
   if(r.subMs>0) rows.push({icon,what:`دونيشن ${u} + نقص`,ms:-r.subMs,text:signed(-r.subMs),short:`-${fmtDur(r.subMs,1)}`});
   return rows.map((x,i)=>({...x,id:r.id+"_"+i,img,label:r.label||""})) }
 }
 return [{id:r.id,icon,img,what:r.label||what,ms,text:signed(ms),short:`${ms<0?"-":"+"}${fmtDur(ms,1)}`}];
}
function rulesForBoard(s,opt={}){ const L=(s&&s.rules&&s.rules.list)||[]; const out=[]; for(const r of L){ if(!r.enabled||r.show===false) continue; if(r.kind==="share"&&opt.noShare) continue; out.push(...ruleView(r)) } return out }
const words=v=>String(v||"").split(/[,،]/).map(x=>x.trim().toLowerCase()).filter(Boolean);
const norm=t=>String(t||"").trim().toLowerCase().replace(/[ً-ْ]/g,"");
/** هل الرسالة تحتوي الكلمة ككلمة مستقلة (أو رمز +/-) */
function hasWord(text,list){ const t=" "+norm(text).replace(/[!؟?.،,]/g," ")+" "; return list.some(w=>w==="+"||w==="-"?t.trim().startsWith(w)||t.includes(" "+w+" "):t.includes(" "+w+" ")) }
function gate(s,r,now,userKey){ const st=s.rstate;
 if(r.cooldownMs>0&&st.last[r.id]&&now-st.last[r.id]<r.cooldownMs) return false;
 if(r.userCooldownMs>0&&userKey){ const k=r.id+"|"+userKey; if(st.user[k]&&now-st.user[k]<r.userCooldownMs) return false }
 if(r.perMin>0){ const w=st.win[r.id]||(st.win[r.id]={t:now,n:0}); if(now-w.t>=60000){ w.t=now; w.n=0 } if(w.n>=r.perMin) return false }
 return true }
function mark(s,r,now,userKey){ const st=s.rstate; st.last[r.id]=now; if(r.perMin>0){ (st.win[r.id]||(st.win[r.id]={t:now,n:0})).n++ }
 if(r.userCooldownMs>0&&userKey){ st.user[r.id+"|"+userKey]=now; const ks=Object.keys(st.user); if(ks.length>3000) for(const k of ks.slice(0,1000)) delete st.user[k] } }
function apply(s,r,ms,now,ev,reason,extra){
 if(!ms) return [];
 if(r.maxMs>0) ms=Math.sign(ms)*Math.min(Math.abs(ms),r.maxMs);
 return subathonOp(s,{op:"add",ms,reason,source:"rule",eventId:ev.id,x:Object.assign({ruleId:r.id,kind:r.kind,user:ev.user?.name||ev.name||"",avatar:ev.user?.avatar||"",icon:r.emoji||(RULE_KINDS[r.kind]||{}).icon,img:r.img||"",gift:ev.gift||"",test:!!ev.test},extra||{})},now);
}
const accum=(s,r,n)=>{ const st=s.rstate.acc; const every=Math.max(1,+r.every||1); st[r.id]=(st[r.id]||0)+n; const k=Math.floor(st[r.id]/every); st[r.id]-=k*every; return k };
function giftRule(L,ev){
 const id=ev.giftId!=null?String(ev.giftId):null, name=norm(ev.gift), per=(ev.diamonds!=null?+ev.diamonds:(+ev.value||0)/Math.max(1,+ev.count||1));
 const gifts=L.filter(r=>r.kind==="gift"&&r.enabled);
 return (id&&gifts.find(r=>r.giftId!=null&&r.giftId!=="*"&&String(r.giftId)===id))
  ||(name&&gifts.find(r=>(r.giftId==null||r.giftId==="")&&!r.minDiamonds&&norm(r.giftName)===name))
  ||gifts.filter(r=>(r.giftId==null||r.giftId==="")&&r.minDiamonds>0&&per>=r.minDiamonds).sort((a,b)=>b.minDiamonds-a.minDiamonds)[0]
  ||gifts.find(r=>r.giftId==="*")||null;
}
/** تطبيق حدث بث على السبثون — ترجع سجلات التغيير (كل سجل يحمل معرّف القاعدة والحدث) */
function subathonOnEvent(s,ev,now,tot){
 migrateRules(s);
 if(!(s.status==="running"||(s.status==="paused"&&s.countWhilePaused))) return [];
 const R=s.rules, out=[];
 if(R.auto!==false){ const L=R.list, who=ev.user?.name||ev.name||"", uk=ev.user?.id||who;
  if(ev.type==="gift"){ const r=giftRule(L,ev); if(r&&gate(s,r,now,uk)){ const cnt=Math.max(1,+ev.count||1);
    let ms; if(r.giftId==="*"&&r.perDiamondMs&&!r.ms){ const per=(ev.diamonds!=null?+ev.diamonds:(+ev.value||0)/cnt); ms=r.perDiamondMs*per*cnt } else { const n=+r.every>1?accum(s,r,cnt):cnt; ms=n*r.ms }
    if(ms){ mark(s,r,now,uk); out.push(...apply(s,r,ms*(r.dir<0?-1:1),now,ev,`${ev.gift||r.giftName||"هدية"}${cnt>1?" ×"+cnt:""} من ${who}`)) } } }
  else if(ev.type==="like"){ for(const r of L.filter(x=>x.kind==="likes"&&x.enabled)){ const n=accum(s,r,+ev.count||0); s.likeAcc=s.rstate.acc[r.id]; if(n>0&&gate(s,r,now)){ mark(s,r,now); out.push(...apply(s,r,n*r.ms*(r.dir<0?-1:1),now,ev,`${n*(+r.every||1)} لايك`)) } } }
  else if(ev.type==="follow"||ev.type==="subscribe"||ev.type==="share"){ const kind=ev.type; for(const r of L.filter(x=>x.kind===kind&&x.enabled)){ const n=+r.every>1?accum(s,r,1):1; if(n>0&&gate(s,r,now,uk)){ mark(s,r,now,uk); out.push(...apply(s,r,n*r.ms*(r.dir<0?-1:1),now,ev,`${kind==="follow"?"متابعة":kind==="subscribe"?"اشتراك":"مشاركة"} ${who}`.trim())) } } }
  else if(ev.type==="comment"){ const t=norm(ev.text); for(const r of L.filter(x=>x.kind==="comment"&&x.enabled&&x.keyword)){ const kw=norm(r.keyword); if(!(t===kw||t.startsWith(kw+" "))) continue; if(!gate(s,r,now,uk)) continue; mark(s,r,now,uk); out.push(...apply(s,r,r.ms*(r.dir<0?-1:1),now,ev,`أمر «${r.keyword}» من ${who}`)) } }
 }
 const G=R.goal;
 if(G&&G.enabled&&!G.reached&&tot){ const v=G.metric==="gifts"?tot.gifts:G.metric==="follows"?tot.follows:tot.likes; if(v>=G.target){ G.reached=true; out.push(...subathonOp(s,{op:"add",ms:G.sec*1000,reason:"تحقيق الهدف ("+G.target+")",source:"event"},now)) } }
 return out;
}
/** الدونيشن المؤكد فقط: «زيد» يزيد و«نقص» ينقص حسب المبلغ، وإجراء افتراضي بدون رسالة */
function donationAction(r,ev){
 const msg=ev.message||"";
 if(hasWord(msg,words(r.subWords))) return "sub"; if(hasWord(msg,words(r.addWords))) return "add";
 return r.defaultAction||"none";
}
function subathonOnDonation(s,ev,now){
 migrateRules(s);
 if(!(s.status==="running"||(s.status==="paused"&&s.countWhilePaused))) return [];
 if(s.rules.auto===false||ev.type!=="donation") return [];
 const out=[];
 for(const r of s.rules.list.filter(x=>x.kind==="donation"&&x.enabled)){
  if(r.currency&&ev.currency&&r.currency!==ev.currency) continue;
  const amt=Math.max(0,+ev.amount||0); if(amt<(+r.minAmount||0)||!amt) continue;
  const act=donationAction(r,ev); if(act==="none") continue;
  const per=act==="sub"?r.subMs:r.addMs; if(!per) continue;
  if(!gate(s,r,now)) continue; mark(s,r,now);
  const ms=Math.round(amt/Math.max(0.01,+r.unit||1)*per)*(act==="sub"?-1:1);
  out.push(...apply(s,r,ms,now,ev,`دونيشن ${amt} ${ev.currency||r.currency} ${act==="sub"?"«نقص»":"«زيد»"} من ${ev.anonymous?"مجهول":(ev.name||"")}`,{donation:amt,currency:ev.currency,action:act}));
  break;
 }
 return out;
}

/** ساعة الخادم: بدء مجدول + انتهاء تلقائي */
function subathonTick(s,now){
 const out=[];
 if(s.status==="idle"&&s.scheduledAt&&now>=s.scheduledAt){ s.scheduledAt=null; out.push(...subathonOp(s,{op:"start"},now)) }
 if(s.status==="running"&&s.endsAt<=now){ s.status="ended"; s.endedAt=s.endsAt; s.remainingMs=0; s.endsAt=null; out.push(log(s,now,0,0,"انتهى السبثون","system")) }
 return out;
}

// ---------- مؤقتات البث المتعددة (كل مؤقت مستقل) ----------
const TIMER_KINDS={elapsed:{label:"مدة البث",dir:"up"},countdown:{label:"عد تنازلي",dir:"down"},break:{label:"استراحة",dir:"down"},challenge:{label:"مؤقت التحدي",dir:"down"},custom:{label:"مخصص",dir:"down"}};
function newTimer(kind="countdown",o={}){
 const k=TIMER_KINDS[kind]||TIMER_KINDS.custom;
 return Object.assign({id:"tm_"+Math.random().toString(36).slice(2,9),kind,name:k.label,dir:k.dir,durationMs:10*MIN,status:"idle",startedAt:null,endsAt:null,accMs:0,remainingMs:10*MIN,prefix:"",endText:"انتهى الوقت",autoLive:false},o);
}
function defaultTimers(){ return [newTimer("elapsed",{id:"stream",name:"مدة البث",prefix:"مدة البث",autoLive:true}),newTimer("break",{name:"الاستراحة",prefix:"راجع بعد",durationMs:5*MIN,remainingMs:5*MIN})] }
function timerValue(t,now){
 if(t.dir==="up") return t.accMs+(t.status==="running"?now-t.startedAt:0);
 return t.status==="running"?Math.max(0,t.endsAt-now):Math.max(0,t.remainingMs);
}
function timerOp(t,op,now){
 switch(op.op){
  case "start": if(t.status==="running") break;
   if(t.status==="ended"||t.status==="idle"){ t.accMs=0; t.remainingMs=t.durationMs }
   t.status="running"; t.startedAt=now; if(t.dir==="down") t.endsAt=now+t.remainingMs; break;
  case "pause": if(t.status!=="running") break; if(t.dir==="up") t.accMs+=now-t.startedAt; else t.remainingMs=Math.max(0,t.endsAt-now); t.status="paused"; t.endsAt=null; break;
  case "resume": if(t.status!=="paused") break; t.status="running"; t.startedAt=now; if(t.dir==="down") t.endsAt=now+t.remainingMs; break;
  case "reset": t.status="idle"; t.accMs=0; t.remainingMs=t.durationMs; t.endsAt=null; t.startedAt=null; break;
  case "add": { const ms=+op.ms||0; if(t.dir==="up"){ t.accMs=Math.max(0,t.accMs+ms) } else if(t.status==="running"){ t.endsAt=Math.max(now,t.endsAt+ms) } else t.remainingMs=Math.max(0,t.remainingMs+ms); break }
  case "config": { const c=op.config||{}; for(const k of ["name","prefix","endText","autoLive"]) if(c[k]!==undefined) t[k]=c[k]; if(c.durationMs!==undefined){ t.durationMs=Math.max(1000,+c.durationMs); if(t.status==="idle") t.remainingMs=t.durationMs } break }
 }
}
function timerTick(t,now){ if(t.dir==="down"&&t.status==="running"&&t.endsAt<=now){ t.status="ended"; t.remainingMs=0; t.endsAt=null; return true } return false }
function fmtClock(ms,showHours=true){ const s=Math.max(0,Math.ceil(ms/1000)), h=Math.floor(s/3600), m=Math.floor(s/60)%60, x=s%60, p=n=>String(n).padStart(2,"0"); return (showHours||h?p(h)+":":"")+p(m)+":"+p(x) }
function fmtDelta(ms){ const a=Math.abs(ms), s=Math.round(a/1000), sign=ms<0?"-":"+";
 if(s<60) return `${sign}${s} ثانية`; if(s<3600){ const m=Math.round(s/60); return `${sign}${m} ${m===1?"دقيقة":m===2?"دقيقتان":m<=10?"دقائق":"دقيقة"}` } const h=+(s/3600).toFixed(1); return `${sign}${h} ${h===1?"ساعة":h===2?"ساعتان":"ساعات"}` }
function newClockState(){ return {subathon:newSubathon(),timers:defaultTimers(),followers:{},latest:{},music:null,tops:{},session:null,reports:[]} }
/** قوالب جاهزة للقواعد */
const RULE_PRESETS={normal:"سبثون عادي (كل التفاعلات تزيد)",compete:"سبثون تنافسي (زيادة ونقصان)",gifts:"سبثون الهدايا فقط",donation:"سبثون الدونيشن فقط",likes:"سبثون التكبيس فقط",all:"سبثون شامل"};
function presetRules(key){ const L=defaultRuleList();
 for(const r of L){ if(key==="normal"){ r.dir=1; if(r.kind==="comment"&&r.keyword==="نقص") r.enabled=false; if(r.kind==="donation") r.subMs=0 }
  else if(key==="compete"){ if(r.kind==="comment") r.enabled=true }
  else if(key==="gifts") r.enabled=r.kind==="gift";
  else if(key==="donation") r.enabled=r.kind==="donation";
  else if(key==="likes") r.enabled=r.kind==="likes";
  else if(key==="all"){ r.enabled=r.kind!=="share"||r.enabled } }
 if(key==="normal") for(const r of L) if(r.kind==="gift") r.dir=1;
 return L }

/* ---- engine/donations.js ---- */
// ====== محرك الدونيشن (التبرعات المالية) ======
// منفصل تماماً عن هدايا TikTok: لا تُجمع المبالغ بالريال مع نقاط الهدايا، ولا تُجمع عملات مختلفة في رقم واحد.
// كل تبرع له معرّف ثابت (المزوّد + معرّف العملية) يمنع احتسابه مرتين، والاسترجاع يُخصم من الإحصائيات والأهداف.

const CURRENCIES={SAR:{sym:"ر.س",name:"ريال سعودي",dec:2},USD:{sym:"$",name:"دولار",dec:2},EUR:{sym:"€",name:"يورو",dec:2},AED:{sym:"د.إ",name:"درهم",dec:2},KWD:{sym:"د.ك",name:"دينار كويتي",dec:3},QAR:{sym:"ر.ق",name:"ريال قطري",dec:2},BHD:{sym:"د.ب",name:"دينار بحريني",dec:3},OMR:{sym:"ر.ع",name:"ريال عماني",dec:3},GBP:{sym:"£",name:"جنيه",dec:2}};

const PROVIDERS={
 moyasar:{name:"ميسّر Moyasar",kind:"صفحة تبرع + Webhook",supported:true,note:"مزود دفع سعودي: مدى، Apple Pay، STC Pay، البطاقات. التبرع يُحتسب بعد التحقق من حالة الدفع paid عبر API ميسّر، والاسترجاع يصل عبر Webhook."},
 streamlabs:{name:"Streamlabs",kind:"Socket API الرسمي",supported:true,note:"يتطلب Socket API Token من إعدادات Streamlabs. يصل حدث donation فقط بعد إتمام الدفع. لا يرسل Streamlabs أحداث الاسترجاع عبر هذا الاتصال."},
 streamelements:{name:"StreamElements",kind:"Astro WebSocket الرسمي",supported:true,note:"اشتراك في channel.tips باستخدام JWT أو OAuth2 أو Overlay Token. يُحتسب التبرع فقط إذا كانت حالته success ومسموح به."},
 streampay:{name:"StreamPay (سعودي)",kind:"Webhook بتوقيع HMAC",supported:false,note:"غير مدعوم حالياً — مخطط لإضافته لاحقاً."},
 paypal:{name:"PayPal مباشر",kind:"—",supported:false,note:"غير مدعوم حالياً — يمكن استقبال تبرعات PayPal عبر Streamlabs أو StreamElements."},
 kofi:{name:"Ko-fi",kind:"—",supported:false,note:"غير مدعوم حالياً."},
};
const PERIODS=[["session","البث الحالي"],["day","اليوم"],["week","الأسبوع"],["month","الشهر"],["all","جميع الأوقات"]];
const WEEKDAYS=["الأحد","الاثنين","الثلاثاء","الأربعاء","الخميس","الجمعة","السبت"];

function fmtMoney(v,cur="SAR"){ const c=CURRENCIES[cur]||{sym:cur,dec:2}; const n=Number(v)||0;
 const s=n.toLocaleString("en-US",{minimumFractionDigits:n%1?Math.min(2,c.dec):0,maximumFractionDigits:c.dec}); return `${s} ${c.sym}` }
function newGoal(o={}){ return Object.assign({id:"dg_"+Math.random().toString(36).slice(2,9),name:"هدف تطوير معدات البث",target:1000,currency:"SAR",base:0,auto:true,startAt:null,endAt:null,paused:false,celebrate:true},o) }
function defaultDonCfg(){ return {
 currency:"SAR",tz:"Asia/Riyadh",weekStart:0,hideAnon:false,anonName:"داعم مجهول",
 goals:[newGoal()],
 alert:{minAmount:1,durationSec:6,showMessage:true,template:"{name} دعم البث بـ {amount}!",sound:true},
 tiers:[{min:0,emoji:"💚",fx:"basic",name:"عادي"},{min:50,emoji:"🔥",fx:"fire",name:"قوي"},{min:200,emoji:"👑",fx:"royal",name:"ملكي"},{min:1000,emoji:"💎",fx:"legend",name:"أسطوري"}],
} }
function emptyDonations(){ return {list:[],sessionStart:Date.now()} }
const net=d=>d.status==="pending"?0:Math.max(0,(+d.amount||0)-(+d.refunded||0));
const donNet=net;

/** تطبيق حدث تبرع أو استرجاع. يرجع true إذا تغيّر شيء */
function applyDonation(DN,ev){
 if(ev.type==="donation"){
  if(!ev.id||DN.list.some(d=>d.id===ev.id)) return false; // منع التكرار بمعرّف العملية
  if(ev.status&&ev.status!=="confirmed") return false; // المعلّق لا يُحتسب
  const amount=Math.round((+ev.amount||0)*1000)/1000; if(!(amount>0)) return false;
  DN.list.push({id:ev.id,provider:ev.provider||"test",name:String(ev.name||"").slice(0,60),anonymous:!!ev.anonymous,avatar:ev.avatar||"",amount,currency:String(ev.currency||"SAR").toUpperCase(),message:String(ev.message||"").slice(0,300),status:"confirmed",refunded:0,test:!!ev.test,t:ev.t||Date.now()});
  if(DN.list.length>20000) DN.list.splice(0,DN.list.length-20000);
  return true }
 if(ev.type==="donation_refund"){ const d=DN.list.find(x=>x.id===ev.id); if(!d) return false;
  const amt=ev.amount==null?d.amount:Math.min(d.amount,+ev.amount||0); if(amt<=d.refunded) return false;
  d.refunded=amt; d.status=d.refunded>=d.amount?"refunded":"partially_refunded"; return true }
 if(ev.type==="donation_session"){ DN.sessionStart=ev.t||Date.now(); return true }
 if(ev.type==="donation_clear_tests"){ const n=DN.list.length; DN.list=DN.list.filter(d=>!d.test); return n!==DN.list.length }
 return false;
}
/** مفتاح الفترة بالمنطقة الزمنية التي يحددها صانع المحتوى (اليوم/الأسبوع ببداية قابلة للتحديد/الشهر) */
function periodKey(t,tz,period,weekStart=0){
 let p; try{ p=Object.fromEntries(new Intl.DateTimeFormat("en-US",{timeZone:tz||"UTC",year:"numeric",month:"2-digit",day:"2-digit",weekday:"short"}).formatToParts(new Date(t)).map(x=>[x.type,x.value])) }catch(e){ return periodKey(t,"UTC",period,weekStart) }
 if(period==="month") return p.year+"-"+p.month;
 if(period==="day") return p.year+"-"+p.month+"-"+p.day;
 if(period==="week"){ const wd=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"].indexOf(p.weekday); const back=(wd-weekStart+7)%7; const d=new Date(Date.UTC(+p.year,+p.month-1,+p.day-back)); return "W"+d.toISOString().slice(0,10) }
 return "all";
}
function inPeriod(d,o){ if(o.period==="all") return true; if(o.period==="session") return d.t>=(o.sessionStart||0); return periodKey(d.t,o.tz,o.period,o.weekStart)===periodKey(o.now,o.tz,o.period,o.weekStart) }
function displayName(d,cfg){ return d.anonymous||(!d.name)?(cfg&&cfg.anonName||"داعم مجهول"):d.name }

/** مجموع كل داعم في فترة وعملة محددة (المجهولون لا يُدمجون معاً) */
function donorTotals(DN,cfg,o){
 const cur=o.currency||cfg.currency, m={};
 for(const d of DN.list){ if(d.currency!==cur||!inPeriod(d,{...o,tz:cfg.tz,weekStart:cfg.weekStart,sessionStart:DN.sessionStart})) continue; if(o.excludeTests&&d.test) continue;
  const v=net(d); if(!v) continue;
  const anon=d.anonymous||!d.name; const k=anon?"anon:"+d.id:"n:"+d.name.toLowerCase();
  const r=m[k]||(m[k]={k,name:displayName(d,cfg),av:anon?"":d.avatar,v:0,c:0,anon}); r.v+=v; r.c++ }
 return Object.values(m).filter(r=>!(o.hideAnon&&r.anon)).sort((a,b)=>b.v-a.v);
}
function recentDonations(DN,cfg,o={}){ return DN.list.filter(d=>net(d)>0&&(!o.currency||d.currency===o.currency)&&!(o.hideAnon&&(d.anonymous||!d.name))).slice(-(o.limit||20)).reverse() }
/**
 * تقدم الهدف من مصدر واحد (قائمة الدونيشن المؤكدة في الغرفة) — كل تصاميم الهدف تقرأ نفس النتيجة.
 * عملة مختلفة عن عملة الهدف تُحوَّل بسعر موثوق (الربط الرسمي أو أسعار محفوظة مع وقتها) — لا نجمع 10 ريال مع 10 دولار كأنها نفس القيمة.
 */
function goalProgress(g,DN,now,rates){
 let cur=+g.base||0, real=+g.base||0, tests=0, skipped=0; const conv=[];
 if(g.auto&&!g.paused) for(const d of DN.list){ const dt=+d.t||0; if(g.startAt&&dt<g.startAt) continue; if(g.endAt&&dt>g.endAt) continue; if(g.countedFrom&&dt<g.countedFrom) continue;
  let v=net(d); if(d.currency!==g.currency){ const c=alConvert(v,d.currency,g.currency,rates&&rates.rates); if(c==null){ skipped++; continue } conv.push({id:d.id,from:d.currency,amount:v,to:c}); v=c }
  cur+=v; if(d.test) tests+=v; else real+=v }
 const target=Math.max(0.01,+g.target||1), c2=Math.round(cur*100)/100;
 return {current:c2,real:Math.round(real*100)/100,tests:Math.round(tests*100)/100,over:Math.max(0,Math.round((cur-target)*100)/100),target,pct:Math.min(100,cur/target*100),rawPct:cur/target*100,remaining:Math.max(0,target-cur),reached:cur>=target,converted:conv,skipped,rateSrc:rates&&rates.source||"",rateAt:rates&&rates.at||""};
}
/** الإحصائيات المالية: التبرعات المؤكدة فقط، بدون التجريبية، ولكل عملة على حدة */
function donationStats(DN,cfg,now){
 const by={};
 for(const d of DN.list){ if(d.test) continue; const v=net(d); const c=by[d.currency]||(by[d.currency]={currency:d.currency,total:0,today:0,week:0,month:0,count:0,max:0,maxDon:null,refunded:0,byProvider:{}});
  c.refunded+=+d.refunded||0; if(!v) continue;
  c.total+=v; c.count++; if(d.amount>c.max){c.max=d.amount;c.maxDon=d}
  c.byProvider[d.provider]=(c.byProvider[d.provider]||0)+v;
  const o={tz:cfg.tz,weekStart:cfg.weekStart,now};
  if(periodKey(d.t,o.tz,"day",o.weekStart)===periodKey(now,o.tz,"day",o.weekStart)) c.today+=v;
  if(periodKey(d.t,o.tz,"week",o.weekStart)===periodKey(now,o.tz,"week",o.weekStart)) c.week+=v;
  if(periodKey(d.t,o.tz,"month",o.weekStart)===periodKey(now,o.tz,"month",o.weekStart)) c.month+=v }
 for(const c of Object.values(by)) c.top=donorTotals(DN,cfg,{period:"all",currency:c.currency,now,excludeTests:true})[0]||null;
 return Object.values(by);
}
function tierFor(cfg,amount){ const t=[...(cfg.tiers||[])].sort((a,b)=>b.min-a.min).find(x=>amount>=x.min); return t||{min:0,emoji:"💚",fx:"basic"} }
function alertText(cfg,d){ return String(cfg.alert.template||"{name} دعم البث بـ {amount}!").replace("{name}",displayName(d,cfg)).replace("{amount}",fmtMoney(d.amount,d.currency)) }

/* ---- engine/latest.js ---- */
// ====== آخر التفاعلات (Latest Events): دوال نقية ======
// يُحفظ آخر حدث حقيقي لكل نوع داخل C.latest (يُحفظ مع حالة الغرفة ويصل لكل الروابط عند إعادة الاتصال).
// قاعدة الصدق: أحداث الاختبار تُعرض على العنصر فقط ولا تُحفظ كآخر حدث حقيقي.
// الدونيشن لا يصل هنا إلا بعد تأكيده من مزود الدفع (مسار التبرعات في الغرفة)، ولا يُخلط بهدايا TikTok.
const LE_KINDS={
 like:{label:"آخر لايك",en:"LAST LIKE",icon:"❤️",ev:"like",title:"آخر لايك",msg:"{count} لايك",status:["يعمل — أحدث حدث إعجاب مستلم من البث","ok"],note:"TikTok يرسل الإعجابات على دفعات؛ المعروض هو صاحب أحدث دفعة إعجاب مستلمة، وليس ترتيباً موثقاً لآخر ضغطة."},
 follow:{label:"آخر متابعة",en:"LAST FOLLOW",icon:"👤",ev:"follow",title:"آخر متابعة",msg:"شكراً على الفولو يا {user}",status:["يعمل — متابعات البث المباشر","ok"]},
 join:{label:"آخر دخول",en:"LAST JOIN",icon:"🚪",ev:"join",title:"آخر دخول",msg:"نورت البث يا {user}",status:["غير مؤكد — يعتمد على وصول أحداث الدخول من اتصال TikTok","warn"],note:"أحداث الدخول قد لا تصل لكل المشاهدين أو قد لا تصل إطلاقاً حسب اتصال TikTok؛ إن لم تصل يبقى العنصر فارغاً ولا نعرض أسماء وهمية."},
 share:{label:"آخر مشاركة",en:"LAST SHARE",icon:"🔁",ev:"share",title:"آخر مشاركة",msg:"شكراً على مشاركة البث",status:["يعمل عند وصول أحداث المشاركة من البث","warn"]},
 donation:{label:"آخر دعم دونيشن",en:"LAST DONATION",icon:"💰",ev:"donation",title:"آخر دعم",msg:"شكراً على دعمك",status:["يعمل — بعد تأكيد مزود التبرعات فقط","ok"],note:"يظهر الدعم المالي فقط بعد تأكيده من مزود التبرعات المتصل، ولا تُحسب هدايا TikTok هنا."},
 gift:{label:"آخر هدية TikTok",en:"LAST GIFT",icon:"🎁",ev:"gift",title:"آخر هدية",msg:"{gift} ×{count}",status:["يعمل — هدايا البث","ok"]},
 comment:{label:"آخر تعليق",en:"LAST COMMENT",icon:"💬",ev:"comment",title:"آخر تعليق",msg:"{text}",status:["يعمل — تعليقات كل المنصات المتصلة","ok"]},
 topDay:{label:"أقوى داعم اليوم",en:"TOP TODAY",icon:"👑",derived:"tops:day",title:"أقوى داعم اليوم",msg:"{count} نقطة هدايا",status:["يعمل — نقاط هدايا TikTok منذ بداية اليوم (توقيت السعودية)","ok"]},
 topWeek:{label:"أقوى داعم الأسبوع",en:"TOP WEEK",icon:"🏆",derived:"tops:week",title:"أقوى داعم الأسبوع",msg:"{count} نقطة هدايا",status:["يعمل — من الأحد إلى اليوم","ok"]},
 topMonth:{label:"أقوى داعم الشهر",en:"TOP MONTH",icon:"💎",derived:"tops:month",title:"أقوى داعم الشهر",msg:"{count} نقطة هدايا",status:["يعمل — منذ بداية الشهر","ok"]},
 topLike:{label:"أكثر شخص كبس",en:"TOP LIKER",icon:"❤️",derived:"lb:likes",title:"أكثر شخص كبس",msg:"{count} لايك",status:["يعمل — دفعات اللايكات المستلمة في هذا البث","ok"]},
 topComment:{label:"أكثر شخص علّق",en:"TOP CHATTER",icon:"💬",derived:"lb:comments",title:"أكثر شخص علّق",msg:"{count} تعليق",status:["يعمل — تعليقات هذا البث","ok"]},
 topShare:{label:"أكثر شخص شارك",en:"TOP SHARER",icon:"🔁",derived:"tops:shares",title:"أكثر شخص شارك",msg:"{count} مشاركة",status:["يعمل عند وصول أحداث المشاركة (اليوم)","warn"]},
 song:{label:"آخر طالب أغنية",en:"LAST SONG REQUEST",icon:"🎵",derived:"music",title:"آخر طلب أغنية",msg:"طلب «{title}»",status:["يعمل — من نظام طلبات الأغاني","ok"]},
 subscribe:{label:"آخر مشترك",en:"LAST SUB",icon:"⭐",ev:"subscribe",title:"آخر مشترك",msg:"يا هلا بالمشترك الجديد",status:["يعمل عند وصول أحداث الاشتراك","warn"]},
};
const LE_MAIN=["like","follow","join","share","donation"];
const KIND_OF={comment:"comment",like:"like",follow:"follow",join:"join",share:"share",donation:"donation",gift:"gift",subscribe:"subscribe"};
const leKindOf=ev=>ev&&KIND_OF[ev.type]||null;

/** تحويل الحدث إلى سجل عرض موحّد */
function leEntry(ev,now){ const k=leKindOf(ev); if(!k) return null;
 const u=ev.user||{}, don=k==="donation";
 const name=don?(ev.anonymous?"داعم مجهول":String(ev.name||"").slice(0,60)):String(u.name||u.nick||u.id||"").slice(0,60);
 const e={id:String(ev.id||k+"_"+now),kind:k,name,uid:don?"":String(u.id||name),av:don?(ev.anonymous?"":ev.avatar||""):(u.avatar||""),at:ev.t||now,test:!!ev.test};
 if(k==="like") e.count=Math.max(0,+ev.count||0);
 if(k==="comment") e.text=String(ev.text||"").slice(0,120);
 if(k==="gift"){ e.count=Math.max(1,+ev.count||1); e.gift=String(ev.gift||"هدية").slice(0,40); e.value=+ev.value||0 }
 if(don){ e.amount=Math.round((+ev.amount||0)*100)/100; e.currency=String(ev.currency||"SAR").toUpperCase(); e.message=String(ev.message||"").slice(0,120) }
 return e }

/** تحديث آخر حدث حقيقي (الغرفة) — اللايكات من نفس المستخدم خلال 15 ثانية تُجمع في نفس السجل */
function latestOnEvent(L,ev,now){ if(!ev||ev.test) return false;
 if(ev.type==="donation_refund"){ const d=L.donation; if(d&&ev.id&&(d.id===ev.id||d.id===ev.ref)){ delete L.donation; return true } return false }
 const e=leEntry(ev,now); if(!e) return false; if(e.kind==="donation"&&!(e.amount>0)) return false;
 const p=L[e.kind];
 if(e.kind==="like"&&p&&p.uid===e.uid&&now-p.at<15000){ p.count+=e.count; p.at=now; p.id=e.id; return true }
 L[e.kind]=e; return true }

/** تعبئة القالب بقيم حقيقية فقط */
function leText(tpl,e,money){ return String(tpl||"").replace(/\{user\}/g,e.name||"").replace(/\{count\}/g,e.count!=null?Number(e.count).toLocaleString("en-US"):"").replace(/\{gift\}/g,e.gift||"").replace(/\{text\}/g,e.text||"").replace(/\{title\}/g,e.title||"").replace(/\{amount\}/g,e.amount!=null&&money?money(e.amount,e.currency):"").trim() }

/** العناصر المشتقة: تُحسب من حالة الغرفة (أقوى داعم بالفترة، الأكثر تفاعلاً، آخر طالب أغنية) — لا أرقام وهمية */
function leDerive(kind,src,lbEntriesFn,topsListFn){ const K=LE_KINDS[kind]; if(!K||!K.derived||!src) return null; const [t,a]=K.derived.split(":"); const now=Date.now()+(src.skew||0);
 let r=null;
 if(t==="tops"){ const L=topsListFn(src.C&&src.C.tops,a,now,180); if(L[0]) r={uid:L[0].id,name:L[0].name,av:L[0].av,count:L[0].v} }
 else if(t==="lb"){ const L=lbEntriesFn({source:a,topN:1},src); const x=L&&L[0]; if(x&&x.v>0) r={uid:String(x.k),name:x.name,av:x.av||"",count:x.v} }
 else if(t==="music"){ const q=src.C&&src.C.music&&src.C.music.lastReq; if(q) r={uid:q.id+"|"+q.qid,name:q.name,av:"",title:q.title,count:null} }
 if(!r) return null; return {id:kind+":"+r.uid,kind,at:now,...r} }

/* ---- engine/tops.js ---- */
// ====== أقوى الداعمين حسب الفترة (اليوم / الأسبوع / الشهر) + أكثر المشاركين ======
// يُحفظ في C.tops مع حالة الغرفة. الوحدة: نقاط هدايا TikTok فقط (لا يُخلط بالدونيشن المالي).
// التوقيت: توقيت صانع المحتوى (الافتراضي السعودية +3)، والأسبوع يبدأ يوم الأحد.
const TOP_CAP=60;
function topsKeys(now,tzMin=180){ const d=new Date(now+tzMin*60000); const y=d.getUTCFullYear(), m=d.getUTCMonth(), day=d.getUTCDate();
 const p=n=>String(n).padStart(2,"0"); const ws=new Date(Date.UTC(y,m,day-d.getUTCDay()));
 return {day:`${y}-${p(m+1)}-${p(day)}`,week:`${ws.getUTCFullYear()}-${p(ws.getUTCMonth()+1)}-${p(ws.getUTCDate())}`,month:`${y}-${p(m+1)}`} }
function bucket(T,period,key){ const b=T[period]; if(!b||b.key!==key) T[period]={key,u:{}}; return T[period] }
function bump(b,u,add){ const id=String(u.id||u.name||""); if(!id) return; const r=b.u[id]||(b.u[id]={id,name:"",av:"",v:0}); r.name=String(u.name||r.name).slice(0,60); if(u.avatar) r.av=u.avatar; r.v+=add; r.at=Date.now();
 const ks=Object.keys(b.u); if(ks.length>TOP_CAP*2){ ks.sort((a,c)=>b.u[c].v-b.u[a].v); for(const k of ks.slice(TOP_CAP)) delete b.u[k] } }
/** تحديث من حدث حقيقي — يرجع true إذا تغيّر */
function topsOnEvent(T,ev,now,tzMin=180){ if(!ev||ev.test||!ev.user) return false; const K=topsKeys(now,tzMin);
 if(ev.type==="gift"){ const v=Math.max(0,(+ev.value||0)*(ev.platform&&ev.platform!=="tiktok"?0:1)); if(!v) return false; for(const p of ["day","week","month"]) bump(bucket(T,p,K[p]),ev.user,v); return true }
 if(ev.type==="share"){ bump(bucket(T,"shares",K.day),ev.user,1); return true }
 return false }
/** القائمة المرتبة لفترة — تُصفّر تلقائياً عند بداية يوم/أسبوع/شهر جديد */
function topsList(T,period,now,tzMin=180){ const K=topsKeys(now,tzMin), key=period==="shares"?K.day:K[period]; const b=T&&T[period];
 if(!b||b.key!==key) return []; return Object.values(b.u).sort((a,c)=>c.v-a.v) }

/* ---- engine/poststats.js ---- */
// ====== إحصائيات نهاية البث: الجلسات والتقارير (دوال نقية) ======
// جلسة بمعرّف فريد تبدأ مع «متصل/مباشر» وتنتهي فقط بعد تأكيد الانقطاع (افتراضياً 90 ثانية) — لا يُعتبر تحديث الصفحة أو انقطاع ثوانٍ نهاية بث.

const PS_END_CONFIRM_MS=90000;
function sessionOnLive(R,live,now){ const C=R.C; C.session=C.session||null;
 if(live){ if(C.session&&C.session.endingAt){ C.session.endingAt=null; return "resumed" }  // انقطاع مؤقت ثم عودة → نفس الجلسة
  if(!C.session||C.session.done){ const id="s"+now.toString(36)+Math.random().toString(36).slice(2,6); C.session={id,startedAt:now,endingAt:null,done:false,acc:null}; R.PSB=null; return "started" } return null }
 if(C.session&&!C.session.done&&!C.session.endingAt){ C.session.endingAt=now; return "ending" } return null }
/** يُستدعى في كل نبضة: إذا استمر الانقطاع فترة التأكيد → تقرير نهائي */
function sessionTick(R,now,confirmMs=PS_END_CONFIRM_MS){ const s=R.C.session; if(!s||s.done||!s.endingAt||now-s.endingAt<confirmMs) return null;
 s.done=true; const rep=buildReport(R,s.startedAt,s.endingAt,{id:s.id}); R.C.reports=[rep,...(R.C.reports||[])].slice(0,30); return rep }
/** لقطة الأرقام عند بداية الجلسة — لحساب أرقام هذه الجلسة فقط وعدم خلطها بما قبلها */
/** عدّاد الجلسة: الأحداث الحقيقية فقط (التجريبية لا تُحتسب) أثناء جلسة مفتوحة.
 * الإجماليات في C.session.acc (تُحفظ مع الغرفة)، وترتيب المستخدمين في R.PSB (خارج C حتى لا يُرسل مع كل رسالة ساعة) */
function sessionOnEvent(R,ev){ const s=R.C.session; if(!s||s.done||!ev||ev.test) return; if((ev.platform||"tiktok")!=="tiktok"&&ev.type==="gift") return;
 const a=s.acc||(s.acc={likes:0,gifts:0,giftCount:0,comments:0,follows:0,subs:0,shares:0});
 if(!R.PSB||R.PSB.id!==s.id) R.PSB={id:s.id,u:{likes:{},gifts:{},comments:{},shares:{}}};
 const u=ev.user||{}, k=u.id||u.name, add=(t,n)=>{ if(!k) return; const m=R.PSB.u[t]; const r=m[k]||(m[k]={name:u.name||k,av:u.avatar||"",v:0}); r.v+=n; if(u.avatar) r.av=u.avatar };
 if(ev.type==="like"){ const n=Math.max(0,+ev.count||0); a.likes+=n; add("likes",n) }
 else if(ev.type==="gift"){ const v=Math.max(0,+ev.value||0), c=Math.max(1,+ev.count||1); a.gifts+=v; a.giftCount+=c; add("gifts",v) }
 else if(ev.type==="comment"){ a.comments++; add("comments",1) }
 else if(ev.type==="follow") a.follows++;
 else if(ev.type==="subscribe") a.subs++;
 else if(ev.type==="share"){ a.shares++; add("shares",1) } }
/** بناء التقرير من بيانات الجلسة الفعلية فقط. غير المتاح = null (يُعرض «غير متاح») */
function buildReport(R,startedAt,endedAt,o={}){ const s=R.C.session&&R.C.session.id===o.id?R.C.session:null, D=R.D||{};
 const acc=s&&s.acc||null, UB=R.PSB&&R.PSB.id===o.id?R.PSB.u:null;
 // تقرير تجريبي بدون جلسة: يُبنى من بيانات الغرفة الحالية ويُعلَّم تجريبياً
 const t=acc||(o.test?{...(D.tot||{}),shares:(D.tot||{}).shares??null}:{likes:0,gifts:0,giftCount:0,comments:0,follows:0,subs:0,shares:0});
 const top=(type,N=10)=>UB?Object.values(UB[type]||{}).filter(x=>x.v>0).sort((a,c)=>c.v-a.v).slice(0,N).map(x=>({name:x.name,av:x.av||"",v:x.v}))
  :(o.test&&type!=="shares"?entries({type,topN:N},D,R.H||[]).filter(x=>x.v>0).map(x=>({name:x.name,av:x.av||"",v:x.v})):[]);
 const DC=R.donCfg||{currency:"USD"}; let donors=[], donTotal=null, donCount=null, cur=DC.currency||"USD";
 try{ const L=((R.DN&&R.DN.list)||[]).filter(d=>!d.test&&d.status!=="refunded"&&d.t>=startedAt&&d.t<=endedAt+60000).map(d=>({...d,amount:Math.max(0,(+d.amount||0)-(+d.refunded||0))})).filter(d=>d.amount>0); if(L.length){ cur=L[0].currency||cur; const same=L.filter(d=>(d.currency||cur)===cur); donTotal=Math.round(same.reduce((a,d)=>a+(+d.amount||0),0)*100)/100; donCount=new Set(same.map(d=>d.name||d.id)).size;
  const by={}; for(const d of same){ const k=d.name||"مجهول"; (by[k]||(by[k]={name:k,av:d.avatar||"",v:0})).v+=+d.amount||0 } donors=Object.values(by).sort((a,b)=>b.v-a.v).slice(0,10).map(x=>({...x,v:Math.round(x.v*100)/100})) } }catch(e){}
 return {id:o.id||"r"+endedAt.toString(36),test:!!o.test,startedAt,endedAt,durationMs:Math.max(0,endedAt-startedAt),
  totals:{likes:t.likes??0,comments:t.comments??0,follows:t.follows??0,gifts:t.gifts??0,giftCount:t.giftCount??0,subs:t.subs??0,shares:t.shares??null,views:null,peakViewers:null,donations:donTotal,donationCurrency:cur,donors:donCount},
  listsSessionOnly:!!UB,lists:{supporters:top("gifts"),donors,likers:top("likes"),sharers:top("shares"),commenters:top("comments")},complete:!o.partial&&!!UB} }
const psDur=ms=>{ const m=Math.round(ms/60000), h=Math.floor(m/60); return h?`${h} س ${m%60} د`:`${m} د` };

// ====== استوديو التقرير: قوالب + رسم Canvas (يعمل في المتصفح؛ الدوال الحسابية نقية) ======
const PS_PALETTES=[["b6o6","بطوط","#0b1020","#2a1458","#ff2d6f","#7c5cff"],["gold","ذهبي ملكي","#140d02","#3a2606","#f5c542","#ffe9a3"],["ocean","المحيط","#021420","#063a5a","#22d3ee","#60a5fa"],["neon","نيون","#05010d","#1a0533","#39ff14","#ff00e5"],["rose","وردي","#1d0612","#4a0f2c","#ff6fa8","#ffc2dc"],["desert","صحراء نجد","#1e1206","#5a3410","#f59e0b","#fcd9a0"],["forest","غابة","#03140b","#0b3a22","#34d399","#bef264"],["ice","جليدي","#0a1622","#1f3b57","#bae6fd","#ffffff"],["fire","ناري","#160300","#4a0e00","#ff5a1f","#ffd000"],["mono","أسود وأبيض","#0a0a0a","#262626","#ffffff","#a3a3a3"],["royal","بنفسجي ملكي","#0e0420","#2e0f5c","#c084fc","#f0abfc"],["light","فاتح","#f8fafc","#e2e8f0","#7c3aed","#0f172a"]];
const PS_LAYOUTS=[["cards","بطاقات"],["glass","زجاجي"],["minimal","بسيط"]];
/** 36 قالباً = 12 لوحة ألوان × 3 أنماط تخطيط (كل تركيبة فريدة) */
const PS_TEMPLATES=PS_PALETTES.flatMap(p=>PS_LAYOUTS.map(l=>({id:p[0]+"-"+l[0],name:p[1]+" · "+l[1],pal:p[0],layout:l[0]})));
const PS_SIZES=[["story","ستوري 1080×1920",1080,1920],["portrait","منشور طولي 1080×1350",1080,1350],["square","مربع 1080×1080",1080,1080],["wide","عريض 1920×1080",1920,1080]];
const PS_STATS=[["duration","⏱️","مدة البث"],["likes","❤️","الإعجابات"],["gifts","💎","قيمة الهدايا"],["giftCount","🎁","عدد الهدايا"],["comments","💬","التعليقات"],["follows","➕","متابعون جدد"],["shares","🔁","المشاركات"],["subs","⭐","الاشتراكات"],["donations","💰","الدعم المالي"],["views","👁️","المشاهدات"],["peakViewers","📈","أعلى مشاهدين"]];
const PS_LISTS=[["supporters","🏆","أكثر الداعمين بالهدايا"],["donors","💰","أكثر الداعمين مالياً"],["likers","❤️","أكثر المكبسين"],["sharers","🔁","أكثر المشاركين"],["commenters","💬","أكثر المعلّقين"]];
const PS_THANKS=["شكراً لكل من حضر ودعم البث ❤️","أنتم السبب في نجاح هذا البث 🙏","نلتقي في البث القادم بإذن الله 👋","شكراً يا أحلى متابعين 🌹","ما قصرتوا، الله يسعدكم 💜"];
function psDefaults(){ return {template:"b6o6-cards",size:"story",name:"",thanks:PS_THANKS[0],thanksColor:"",thanksSize:44,font:"Readex Pro",
 stats:Object.fromEntries(PS_STATS.map(([k])=>[k,!["views","peakViewers"].includes(k)])),showUnavailable:true,
 lists:{supporters:5,donors:3,likers:5,sharers:3,commenters:3}} }
const psNum=v=>Number(v).toLocaleString("en-US");
/** قيمة المؤشر كنص؛ null = غير متاح (لا نخترع أرقاماً) */
function psStatValue(rep,k){ if(k==="duration") return psDur(rep.durationMs||0); const v=rep.totals?rep.totals[k]:null;
 if(v==null) return null; if(k==="donations") return psNum(v)+" "+(rep.totals.donationCurrency||""); return psNum(v) }
/** المؤشرات والقوائم المعروضة فعلاً حسب الإعدادات */
function psSections(rep,o){ o={...psDefaults(),...o};
 const stats=PS_STATS.filter(([k])=>o.stats[k]).map(([k,ic,lb])=>({k,ic,lb,v:psStatValue(rep,k)})).filter(s=>s.v!=null||o.showUnavailable);
 const lists=PS_LISTS.map(([k,ic,lb])=>({k,ic,lb,n:+(o.lists[k]||0),rows:((rep.lists||{})[k]||[]).slice(0,+(o.lists[k]||0))})).filter(l=>l.n>0&&(l.rows.length||o.showUnavailable));
 return {stats,lists} }
function psCanvasSize(id){ const s=PS_SIZES.find(x=>x[0]===id)||PS_SIZES[0]; return [s[2],s[3]] }

/** رسم التقرير على Canvas. imgs: خريطة رابط→صورة محمّلة (غير المتاحة → الحرف الأول) */
function psDraw(cv,rep,o,imgs={}){ o={...psDefaults(),...o}; const [W,H]=psCanvasSize(o.size); cv.width=W; cv.height=H; const x=cv.getContext("2d");
 const T=PS_TEMPLATES.find(t=>t.id===o.template)||PS_TEMPLATES[0], P=PS_PALETTES.find(p=>p[0]===T.pal), [,,bg1,bg2,ac,ac2]=P, L=T.layout, light=T.pal==="light";
 const fg=light?"#0f172a":"#ffffff", mut=light?"#475569":"rgba(255,255,255,.65)", F=o.font||"Readex Pro", fam=`"${F}","Readex Pro","Changa","Noto Sans Arabic",sans-serif`;
 const g=x.createLinearGradient(0,0,W*.4,H); g.addColorStop(0,bg1); g.addColorStop(1,bg2); x.fillStyle=g; x.fillRect(0,0,W,H);
 x.globalAlpha=light?.18:.28; for(const [cx,cy,r,c] of [[W*.9,H*.06,W*.45,ac],[W*.05,H*.95,W*.5,ac2]]){ const rg=x.createRadialGradient(cx,cy,0,cx,cy,r); rg.addColorStop(0,c); rg.addColorStop(1,"transparent"); x.fillStyle=rg; x.fillRect(0,0,W,H) } x.globalAlpha=1;
 x.direction="rtl"; x.textBaseline="middle";
 const {stats,lists}=psSections(rep,o), wide=W>H*1.2, pad=Math.round(Math.min(W,H)*.06);
 const rr=(X,Y,w,h,r)=>{ x.beginPath(); x.roundRect?x.roundRect(X,Y,w,h,r):x.rect(X,Y,w,h) };
 const box=(X,Y,w,h,s)=>{ if(L==="minimal"){ x.strokeStyle=light?"#cbd5e1":"rgba(255,255,255,.14)"; x.lineWidth=2*s; x.beginPath(); x.moveTo(X,Y+h); x.lineTo(X+w,Y+h); x.stroke(); return }
  rr(X,Y,w,h,22*s); x.fillStyle=L==="glass"?(light?"rgba(255,255,255,.55)":"rgba(255,255,255,.07)"):(light?"#ffffff":"rgba(0,0,0,.35)"); x.fill(); if(L==="glass"){ x.strokeStyle=ac+"88"; x.lineWidth=2*s; x.stroke() } };
 const fit=(t,max)=>{ t=String(t??""); if(x.measureText(t).width<=max) return t; while(t.length>1&&x.measureText(t+"…").width>max) t=t.slice(0,-1); return t+"…" };
 const txt=(t,X,Y,sz,c,al="right",wt=700,max)=>{ x.font=`${wt} ${sz}px ${fam}`; x.fillStyle=c; x.textAlign=al; x.fillText(max?fit(t,max):t,X,Y) };
 // يرسم عموداً (أو يقيس ارتفاعه فقط عند dry) — للتكيّف التلقائي مع المقاس
 const head=(X,Y,w,s,dry)=>{ const h=150*s; if(dry) return h; txt("إحصائيات البث",X+w,Y+40*s,64*s,fg,"right",900,w); txt([o.name||"",new Date(rep.endedAt||Date.now()).toLocaleDateString("ar-SA-u-ca-gregory-nu-latn"),rep.test?"🧪 تقرير تجريبي":""].filter(Boolean).join("  •  "),X+w,Y+110*s,30*s,mut,"right",500,w); return h };
 const tiles=(X,Y,w,s,dry)=>{ if(!stats.length) return 0; const cols=w>1400*s?4:3, gap=18*s, tw=(w-gap*(cols-1))/cols, th=150*s, rows=Math.ceil(stats.length/cols), h=rows*th+(rows-1)*gap+30*s; if(dry) return h;
  stats.forEach((st,i)=>{ const c=i%cols, r=Math.floor(i/cols), tx=X+w-(c+1)*tw-c*gap, ty=Y+r*(th+gap); box(tx,ty,tw,th,s);
   txt(st.ic,tx+tw-24*s,ty+42*s,36*s,fg,"right",400); txt(st.v==null?"غير متاح":st.v,tx+tw/2,ty+80*s,(st.v==null?32:50)*s,st.v==null?mut:ac,"center",900,tw-20*s); txt(st.lb,tx+tw/2,ty+124*s,26*s,mut,"center",600,tw-20*s) }); return h };
 const listBlock=(l,X,Y,w,s,dry)=>{ const rh=62*s, h=76*s+Math.max(1,l.rows.length)*rh+20*s; if(dry) return h; box(X,Y,w,h,s); txt(l.ic+" "+l.lb,X+w-24*s,Y+40*s,32*s,fg,"right",800,w-48*s);
  if(!l.rows.length) txt("غير متاح لهذه الجلسة",X+w/2,Y+76*s+rh/2,26*s,mut,"center",500);
  l.rows.forEach((r,i)=>{ const ry=Y+76*s+i*rh+rh/2, ax=X+w-24*s-22*s-46*s; const med=["#f5c542","#cbd5e1","#d97706"][i];
   x.beginPath(); x.arc(X+w-24*s-22*s,ry,22*s,0,7); x.fillStyle=med||(light?"#e2e8f0":"rgba(255,255,255,.12)"); x.fill(); txt(String(i+1),X+w-24*s-22*s,ry+2*s,24*s,med?"#111":fg,"center",900);
   x.save(); x.beginPath(); x.arc(ax,ry,24*s,0,7); x.clip(); const im=r.av&&imgs[r.av]; if(im) x.drawImage(im,ax-24*s,ry-24*s,48*s,48*s); else { x.fillStyle=ac2; x.fillRect(ax-24*s,ry-24*s,48*s,48*s); txt((r.name||"?").trim().charAt(0),ax,ry+2*s,24*s,light?"#fff":"#111","center",900) } x.restore();
   x.font=`800 ${28*s}px ${fam}`; const vw=x.measureText(psNum(r.v)).width; txt(r.name,ax-36*s,ry,28*s,fg,"right",600,w-(24+44+48+60)*s-vw-30*s); txt(psNum(r.v),X+24*s,ry,28*s,ac,"left",800) }); return h };
 const listsCol=(X,Y,w,s,dry,cols)=>{ const gap=18*s, cw=(w-gap*(cols-1))/cols, colY=Array(cols).fill(0); for(const l of lists){ const c=colY.indexOf(Math.min(...colY)); const h=listBlock(l,0,0,cw,s,true); if(!dry) listBlock(l,X+w-(c+1)*cw-c*gap,Y+colY[c],cw,s,false); colY[c]+=h+gap } return lists.length?Math.max(...colY):0 };
 const thanks=(X,Y,w,s,dry)=>{ if(!o.thanks) return 0; const sz=(+o.thanksSize||44)*s, h=sz*1.9; if(dry) return h; txt(o.thanks,X+w/2,Y+h/2,sz,o.thanksColor||ac2,"center",800,w); return h };
 const foot=(s)=>txt("B6O6 Streaming",W/2,H-pad*.55,24*s,mut,"center",600);
 const plan=(s,dry)=>{ const g2=26*s; if(wide){ const cw=(W-pad*3)/2, A=pad*2+cw, Bx=pad; let y=pad; y+=head(A,y,cw,s,dry)+g2; y+=tiles(A,y,cw,s,dry)+g2; y+=thanks(A,y,cw,s,dry); const yl=pad+listsCol(Bx,pad,cw,s,dry,lists.length>2?2:1); return Math.max(y,yl)+pad }
  let y=pad; const w=W-pad*2; y+=head(pad,y,w,s,dry)+g2; y+=tiles(pad,y,w,s,dry)+g2; y+=listsCol(pad,y,w,s,dry,H>1500?(lists.length>3?2:1):2); y+=thanks(pad,y,w,s,dry); return y+pad };
 let s=1; for(let i=0;i<6;i++){ const need=plan(s,true)+40; if(need<=H) break; s*=Math.max(.6,(H-40)/need) }  // تصغير تلقائي حتى يتسع كل شيء
 plan(s,false); foot(s); return {scale:s,W,H} }
/** تحميل صور الملفات الشخصية بأمان: crossOrigin — ما يفشل أو يلوّث الـCanvas يُستبدل بالحرف الأول */
function psLoadImages(rep){ const urls=[...new Set(Object.values(rep.lists||{}).flat().map(r=>r.av).filter(Boolean))].slice(0,60), out={};
 return Promise.all(urls.map(u=>new Promise(res=>{ const im=new Image(); im.crossOrigin="anonymous"; const done=ok=>{ if(ok){ try{ const c=document.createElement("canvas"); c.width=c.height=1; const cx=c.getContext("2d"); cx.drawImage(im,0,0,1,1); cx.getImageData(0,0,1,1); out[u]=im }catch(e){} } res() };
  im.onload=()=>done(true); im.onerror=()=>done(false); setTimeout(()=>done(false),4000); im.src=u }))).then(()=>out) }

/* ---- engine/events.js ---- */
// ====== محرك الأحداث الموحد | Event Normalization + Event Bus ======
// كل مصدر (TikTok / YouTube / Kick / Twitch / مزودو الدونيشن / لوحة التحكم) يمر من هنا قبل الغرفة.
// القاعدة: كل نوع له وحدة قياس ومصدر مستقل — لا تُخلط هدايا TikTok بالدونيشن المالي ولا باشتراكات المنصات.
// ملاحظة توافق: أحداث TikTok تحتفظ بمعرّفها الأصلي (الأنظمة الحالية ومنع التكرار تعتمد عليه)،
// وأحداث بقية المنصات تُسبق باسم المنصة لمنع تصادم المعرفات بين المنصات.

/** حالة دعم الميزة: مدعومة · تتطلب تفويضاً · تجريبية · غير متاحة حالياً */
const CAP={ok:["مدعومة","ok"],auth:["تتطلب تفويضاً","warn"],beta:["تجريبية","warn"],no:["غير متاحة حالياً","bad"]};

/** سجل المنصات — قابل للتوسعة بإضافة مدخل جديد فقط */
const LIVE_PLATFORMS={
 tiktok:{name:"TikTok LIVE",color:"#ff0050",color2:"#00f2ea",short:"TT",
  connect:"اسم المستخدم فقط (بدون كلمة مرور) عبر اتصال LIVE غير رسمي؛ لا توجد واجهة رسمية عامة لأحداث LIVE",
  caps:{comment:"beta",like:"beta",gift:"beta",follow:"beta",share:"beta",join:"beta",subscribe:"beta",viewers:"beta",sendChat:"no",moderate:"no"}},
 youtube:{name:"YouTube Live",color:"#ff0000",color2:"#ffffff",short:"YT",
  connect:"Google OAuth + YouTube Data API v3 (liveChatMessages) — المفاتيح على الخادم فقط",
  caps:{comment:"auth",superchat:"auth",subscribe:"auth",viewers:"auth",like:"no",share:"no",join:"no",follow:"no",sendChat:"auth",moderate:"auth"}},
 kick:{name:"Kick",color:"#53fc18",color2:"#0b0e0f",short:"KC",
  connect:"Kick OAuth 2.1 + Webhooks الرسمية (chat.message.sent, channel.followed, channel.subscription.*)",
  caps:{comment:"auth",follow:"auth",subscribe:"auth",gift:"auth",viewers:"beta",sendChat:"auth",moderate:"auth",like:"no",share:"no",join:"no"}},
 twitch:{name:"Twitch",color:"#9146ff",color2:"#ffffff",short:"TW",
  connect:"Twitch OAuth + EventSub WebSocket (channel.chat.message, channel.follow, channel.subscribe, channel.cheer)",
  caps:{comment:"auth",follow:"auth",subscribe:"auth",cheer:"auth",raid:"auth",viewers:"auth",sendChat:"auth",moderate:"auth",like:"no",share:"no",join:"no"}},
};
const PLATFORM_IDS=Object.keys(LIVE_PLATFORMS);
const DONATION_SOURCES=["streamlabs","streamelements","kofi","stripe","paypal","test"];

/** أنواع الأحداث ووحدة قياس كل نوع */
const EVENT_TYPES={
 comment:{unit:"message",label:"تعليق"}, like:{unit:"likes",label:"لايك"}, gift:{unit:"platform_coins",label:"هدية منصة"},
 follow:{unit:"count",label:"متابعة"}, share:{unit:"count",label:"مشاركة"}, join:{unit:"count",label:"دخول"},
 subscribe:{unit:"platform_sub",label:"اشتراك منصة"}, superchat:{unit:"currency",label:"Super Chat"}, cheer:{unit:"bits",label:"Bits"}, raid:{unit:"viewers",label:"غارة"},
 donation:{unit:"currency",label:"دونيشن مالي"}, donation_refund:{unit:"currency",label:"استرجاع دونيشن"}, donation_session:{unit:"none",label:"جلسة دونيشن"}, donation_clear_tests:{unit:"none",label:"مسح تجارب الدونيشن"},
};
const evS=(v,n)=>String(v??"").slice(0,n);
const evN=(v,min=0,max=1e12)=>{ const x=+v; return Number.isFinite(x)?Math.min(max,Math.max(min,x)):0 };

/**
 * يحوّل أي حدث خام إلى الصيغة الموحدة مع الإبقاء على الحقول التي تعتمد عليها الأنظمة الحالية.
 * الصيغة: { id, platform, type, user:{id,name,avatar,mod,sub}, at, data, source, verified, test, unit, ...حقول التوافق }
 * يرجع null للحدث غير الصالح.
 */
function normalizeEvent(raw,ctx={}){
 if(!raw||typeof raw!=="object"||!raw.type||!EVENT_TYPES[raw.type]) return null;
 const platform=LIVE_PLATFORMS[raw.platform]?raw.platform:(LIVE_PLATFORMS[ctx.platform]?ctx.platform:(raw.type.startsWith("donation")?"donation":"tiktok"));
 const ev={...raw};
 ev.platform=platform;
 ev.source=evS(raw.source||ctx.source||(platform==="donation"?raw.provider||"provider":platform),40);
 ev.at=evN(raw.at||raw.t||ctx.now||Date.now(),0,9e15);
 ev.unit=EVENT_TYPES[raw.type].unit;
 ev.test=!!(raw.test||raw.provider==="test");
 // التحقق: الدونيشن موثّق فقط إذا جاء من مزوّد تحقق منه الخادم؛ أحداث المنصات موثّقة بقدر مصدرها
 ev.verified=raw.type.startsWith("donation")?!!(raw.verified??(raw.provider&&raw.provider!=="test")):(raw.verified??!ev.test);
 if(raw.id!=null){ const id=evS(raw.id,160); ev.id=platform==="tiktok"||platform==="donation"||id.startsWith(platform+":")?id:platform+":"+id }
 if(raw.user){ const u=raw.user; ev.user={...u,id:evS(u.id??u.uniqueId??u.name,120),name:evS(u.name??u.nick??u.nickname??u.id,80),avatar:evS(u.avatar||"",600)} }
 // فصل صارم بين الوحدات
 if(raw.type==="like") ev.count=evN(raw.count,0,1e7);
 if(raw.type==="gift"){ ev.count=Math.max(1,evN(raw.count,1,1e6)); ev.value=evN(raw.value,0,1e9); delete ev.amount; delete ev.currency }
 if(raw.type==="donation"){ ev.amount=Math.round(evN(raw.amount,0,1e7)*100)/100; ev.currency=evS(raw.currency||"USD",8).toUpperCase(); ev.platform="donation" }
 // الاسترجاع: غياب المبلغ يعني استرجاعاً كاملاً — لا نحوّله إلى صفر
 if(raw.type==="donation_refund"){ if(raw.amount!=null) ev.amount=Math.round(evN(raw.amount,0,1e7)*100)/100; if(raw.currency) ev.currency=evS(raw.currency,8).toUpperCase(); ev.platform="donation" }
 if(raw.type==="comment") ev.text=evS(raw.text,500);
 ev.data={...(raw.data||{})};
 return ev }

/** منع التكرار بذاكرة محدودة (LRU) — يُستخدم في الحافلة وعند إعادة الاتصال */
function createDedupe(cap=8000){ const m=new Map();
 return { has:id=>m.has(id), add(id){ if(!id) return true; if(m.has(id)) return false; m.set(id,1); if(m.size>cap){ const it=m.keys(); for(let i=0;i<cap/4;i++) m.delete(it.next().value) } return true }, get size(){ return m.size } } }

/** حافلة الأحداث المركزية: اتصال واحد لكل مصدر يوزّع على كل الأنظمة والعناصر */
class EventBus{
 constructor(opts={}){ this.subs=new Map(); this.dd=createDedupe(opts.cap||8000); this.stats={in:0,out:0,dup:0,bad:0,byType:{},byPlatform:{},lastAt:0,lat:[]} }
 on(type,fn){ if(!this.subs.has(type)) this.subs.set(type,new Set()); this.subs.get(type).add(fn); return ()=>this.subs.get(type)?.delete(fn) }
 /** يطبّع ثم يمنع التكرار ثم يوزّع. يرجع الحدث الموحد أو null */
 emit(raw,ctx={}){ this.stats.in++; const ev=normalizeEvent(raw,ctx); if(!ev){ this.stats.bad++; return null }
  if(ev.id&&!this.dd.add(ev.id)){ this.stats.dup++; return null }
  const st=this.stats; st.out++; st.byType[ev.type]=(st.byType[ev.type]||0)+1; st.byPlatform[ev.platform]=(st.byPlatform[ev.platform]||0)+1; st.lastAt=ev.at;
  const now=ctx.now||Date.now(); if(raw.at||raw.t){ st.lat.push(Math.max(0,now-ev.at)); if(st.lat.length>200) st.lat.shift() }
  for(const k of [ev.type,"*"]) for(const fn of this.subs.get(k)||[]) try{ fn(ev) }catch(e){ st.err=(st.err||0)+1 }
  return ev }
 latency(){ const a=[...this.stats.lat].sort((x,y)=>x-y); if(!a.length) return null; return {p50:a[Math.floor(a.length*.5)],p95:a[Math.floor(a.length*.95)],n:a.length} }
}

/** ملخص حالة الدعم لكل منصة/ميزة لعرضه في الواجهة */
function capabilityTable(){ return PLATFORM_IDS.map(p=>({platform:p,name:LIVE_PLATFORMS[p].name,connect:LIVE_PLATFORMS[p].connect,caps:Object.entries(LIVE_PLATFORMS[p].caps).map(([k,v])=>({feature:k,status:v,label:CAP[v][0],tone:CAP[v][1]}))})) }

/* ---- engine/platforms.js ---- */
// ====== ربط المنصات: تحويل حمولات الواجهات الرسمية إلى الأحداث الموحدة + إعدادات OAuth + أدلة الربط ======
// دوال نقية قابلة للاختبار بدون مفاتيح. الاتصال الفعلي في src/server/platforms.ts (المفاتيح على الخادم فقط).

/** إعدادات OAuth الرسمية لكل منصة (المتغيرات المطلوبة في بيئة الخادم) */
const OAUTH={
 youtube:{authorize:"https://accounts.google.com/o/oauth2/v2/auth",token:"https://oauth2.googleapis.com/token",scopes:["https://www.googleapis.com/auth/youtube.readonly","https://www.googleapis.com/auth/youtube.force-ssl"],env:["YOUTUBE_CLIENT_ID","YOUTUBE_CLIENT_SECRET"],extra:{access_type:"offline",prompt:"consent"}},
 twitch:{authorize:"https://id.twitch.tv/oauth2/authorize",token:"https://id.twitch.tv/oauth2/token",scopes:["user:read:chat","user:write:chat","moderator:read:followers","channel:read:subscriptions","bits:read","moderator:manage:banned_users"],env:["TWITCH_CLIENT_ID","TWITCH_CLIENT_SECRET"]},
 kick:{authorize:"https://id.kick.com/oauth/authorize",token:"https://id.kick.com/oauth/token",scopes:["user:read","channel:read","chat:write","events:subscribe","moderation:ban"],env:["KICK_CLIENT_ID","KICK_CLIENT_SECRET"],pkce:true},
};
/** رابط التفويض — يرجع null إذا لم تُضبط المفاتيح (لا نعرض اتصالاً وهمياً) */
function oauthUrl(platform,env,{redirect,state,challenge}){ const c=OAUTH[platform]; if(!c) return null; const id=env[c.env[0]]; if(!id||!env[c.env[1]]) return null;
 const p=new URLSearchParams({client_id:id,redirect_uri:redirect,response_type:"code",scope:c.scopes.join(" "),state,...(c.extra||{})});
 if(c.pkce&&challenge){ p.set("code_challenge",challenge); p.set("code_challenge_method","S256") }
 return c.authorize+"?"+p.toString() }
const oauthMissing=(platform,env)=>(OAUTH[platform]?.env||[]).filter(k=>!env[k]);

const u_=(id,name,avatar,extra)=>({id:String(id||name||""),name:String(name||id||""),avatar:avatar||"",...extra});

/** Twitch EventSub (WebSocket) → حدث موحد. https://dev.twitch.tv/docs/eventsub/eventsub-subscription-types */
function twitchToEvent(msg){ const t=msg?.metadata?.subscription_type||msg?.payload?.subscription?.type, e=msg?.payload?.event; if(!t||!e) return null; const mid=msg.metadata?.message_id;
 const badges=new Set((e.badges||[]).map(b=>b.set_id));
 switch(t){
  case "channel.chat.message": return {platform:"twitch",type:"comment",id:e.message_id||mid,user:u_(e.chatter_user_id,e.chatter_user_name,"",{mod:badges.has("moderator"),sub:badges.has("subscriber")||badges.has("founder"),owner:badges.has("broadcaster")}),text:e.message?.text||"",source:"twitch-eventsub",verified:true};
  case "channel.follow": return {platform:"twitch",type:"follow",id:mid,user:u_(e.user_id,e.user_name),source:"twitch-eventsub",verified:true};
  case "channel.subscribe": return {platform:"twitch",type:"subscribe",id:mid,user:u_(e.user_id,e.user_name),data:{tier:e.tier,gift:!!e.is_gift},source:"twitch-eventsub",verified:true};
  case "channel.subscription.gift": return {platform:"twitch",type:"subscribe",id:mid,user:u_(e.user_id,e.is_anonymous?"مجهول":e.user_name),data:{tier:e.tier,giftCount:e.total},source:"twitch-eventsub",verified:true};
  case "channel.cheer": return {platform:"twitch",type:"cheer",id:mid,user:u_(e.user_id,e.is_anonymous?"مجهول":e.user_name),bits:e.bits,count:e.bits,text:e.message||"",source:"twitch-eventsub",verified:true};
  case "channel.raid": return {platform:"twitch",type:"raid",id:mid,user:u_(e.from_broadcaster_user_id,e.from_broadcaster_user_name),viewers:e.viewers,source:"twitch-eventsub",verified:true};
 } return null }

/** Kick Webhooks الرسمية → حدث موحد. https://docs.kick.com/events/event-types */
function kickToEvent(type,b,messageId){ if(!type||!b) return null; const s=b.sender||b.follower||b.subscriber||b.gifter||{};
 const user=u_(s.user_id,s.username,s.profile_picture,{mod:!!(s.identity?.badges||[]).find(x=>x.type==="moderator"),sub:!!(s.identity?.badges||[]).find(x=>x.type==="subscriber"),owner:!!(s.identity?.badges||[]).find(x=>x.type==="broadcaster")});
 switch(type){
  case "chat.message.sent": return {platform:"kick",type:"comment",id:b.message_id||messageId,user,text:b.content||"",source:"kick-webhook",verified:true};
  case "channel.followed": return {platform:"kick",type:"follow",id:messageId,user,source:"kick-webhook",verified:true};
  case "channel.subscription.new": case "channel.subscription.renewal": return {platform:"kick",type:"subscribe",id:messageId,user,data:{months:b.duration},source:"kick-webhook",verified:true};
  case "channel.subscription.gifts": return {platform:"kick",type:"subscribe",id:messageId,user:u_(s.user_id,s.is_anonymous?"مجهول":s.username,s.profile_picture),data:{giftCount:(b.giftees||[]).length},source:"kick-webhook",verified:true};
  case "kicks.gifted": return {platform:"kick",type:"gift",id:messageId,user,gift:b.gift?.name||"Kicks",count:1,value:+(b.gift?.amount||0),source:"kick-webhook",verified:true};
 } return null }

/** YouTube liveChatMessages.list → أحداث موحدة. https://developers.google.com/youtube/v3/live/docs/liveChatMessages */
function youtubeToEvents(items){ const out=[]; for(const it of items||[]){ const sn=it.snippet||{}, a=it.authorDetails||{};
  const user=u_(a.channelId,a.displayName,a.profileImageUrl,{mod:!!a.isChatModerator,sub:!!a.isChatSponsor,owner:!!a.isChatOwner});
  const base={platform:"youtube",id:it.id,user,source:"youtube-data-api",verified:true,at:sn.publishedAt?Date.parse(sn.publishedAt):undefined};
  if(sn.type==="textMessageEvent") out.push({...base,type:"comment",text:sn.displayMessage||sn.textMessageDetails?.messageText||""});
  else if(sn.type==="superChatEvent"){ const d=sn.superChatDetails||{}; out.push({...base,type:"superchat",amount:(+d.amountMicros||0)/1e6,currency:d.currency,text:d.userComment||""}) }
  else if(sn.type==="newSponsorEvent"||sn.type==="memberMilestoneChatEvent") out.push({...base,type:"subscribe"}) }
 return out }

