const VARS=[["{username}","اسم المشاهد"],["{subathon_remaining}","الوقت المتبقي في السبثون"],["{likes_total}","مجموع التكبيس"],["{likes_goal}","هدف التكبيس الحالي"],["{likes_remaining}","المتبقي لهدف التكبيس"],["{support_goal}","هدف الدعم الحالي"],["{top_supporter}","المتصدر في الدعم"],["{top_liker}","متصدر التكبيس"],["{socials}","كل الحسابات"],["{social_tiktok}","حساب TikTok"],["{social_instagram}","حساب Instagram"],["{social_roblox}","حساب Roblox"],["{social_fortnite}","حساب Fortnite"],["{gift_name}","اسم الهدية"],["{gift_count}","عدد الهدايا"],["{amount}","المبلغ"]];

