  let E=out?(EXITS[id]||EXITS[EXIT_OF[id]]):ENTRANCES[id]; if(!E) E=out?EXITS.fadeOut:ENTRANCES.fade;
  if(reduced()) E=out?EXITS.fadeOut:ENTRANCES.fade;
