  const msgs=String(w.msgs||FA_MSGS[0]).split("\n").map(s=>s.trim()).filter(Boolean), tpl=it.merged?`❤️ شكراً لـ ${it.count} متابعاً جديداً!`:msgs[w.msgRandom?Math.floor(Math.random()*msgs.length):0]||FA_MSGS[0];
