  const s=R.C.subathon, added=R.logs.filter(x=>x.deltaMs>0).reduce((a,x)=>a+x.deltaMs,0), removed=R.logs.filter(x=>x.deltaMs<0).reduce((a,x)=>a+x.deltaMs,0);
  const st_=R.C.timers.find(t=>t.id==="stream");
