 const rng=(f,l,a,b,st,v,fmt)=>`<div class="fld"><label>${l}: <b id="v_${f}">${fmt?fmt(v):v}</b></label><input type="range" min="${a}" max="${b}" step="${st}" value="${v}" data-wf="${f}" data-wid="${w.id}"></div>`;
